query DiseaseDrugReports($diseaseId: String!) {
  disease(efoId: $diseaseId) {
    id
    name
    drugAndClinicalCandidates {
      count
      rows {
        id
        maxClinicalStage
        drug { id name maximumClinicalStage parentMolecule { id name } }
        clinicalReports {
          id
          type
          source
          provider
          origin
          clinicalStage
          phaseFromSource
          year
          countries
          title
          url
          qualityControls
          diseases { diseaseFromSource disease { id name } }
          drugs { drugFromSource drug { id name } }
        }
      }
    }
  }
}
